const categoryGroups={'Portraits & people':['Professional portraits','Prom & creative portraits'],'Events & performance':['Events & graduations','Music & performance']};
function categoryMatches(g,c){return (c==='Portraits & people'&&g.id==='laudem-recital')||c==='All work'||g.category===c||categoryGroups[c]?.includes(g.category);}
const portfolioRoot=new URL('./',document.currentScript.src);
const $=id=>document.getElementById(id);let catalog=[],view=[],photoIndex=0,momentIndex=0,returnFocus=null,collections=[],activeProject=null,shown=0;
function imageCard(p){const figure=document.createElement('figure');figure.className='photo';const button=document.createElement('button');button.type='button';button.setAttribute('aria-label',`Open ${p.alt}`);const img=document.createElement('img');img.src=p.src;img.alt=p.alt;img.width=p.width;img.height=p.height;img.loading='lazy';img.decoding='async';if(p.position)img.style.objectPosition=p.position;button.append(img);button.addEventListener('click',()=>openPhoto(p));const caption=document.createElement('figcaption');const label=document.createElement('span');label.textContent=p.label;const arrow=document.createElement('span');arrow.textContent='↗';arrow.setAttribute('aria-hidden','true');caption.append(label,arrow);figure.append(button,caption);return figure;}
function render(id,photos){$(id).replaceChildren(...photos.map(imageCard));}
function openPhoto(p){view=p.collection?collections.find(g=>g.id===p.collection).photos:catalog.filter(q=>q.category===p.category);photoIndex=view.findIndex(q=>q.id===p.id);returnFocus=document.activeElement;showPhoto();$('lightbox').showModal();document.body.style.overflow='hidden';}
function showPhoto(){const p=view[photoIndex];$('full-photo').src=p.src;$('full-photo').alt=p.alt;$('photo-label').textContent=p.label;$('photo-count').textContent=`${photoIndex+1} / ${view.length}`;}
function movePhoto(step){photoIndex=(photoIndex+step+view.length)%view.length;showPhoto();}
function closePhoto(){if($('lightbox').open)$('lightbox').close();}
$('close').addEventListener('click',closePhoto);$('lightbox').addEventListener('close',()=>{document.body.style.overflow='';returnFocus?.focus();});$('previous').addEventListener('click',()=>movePhoto(-1));$('next').addEventListener('click',()=>movePhoto(1));$('lightbox').addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();movePhoto(-1);}if(e.key==='ArrowRight'){e.preventDefault();movePhoto(1);}});
function filter(category){
 const groups=collections.filter(g=>categoryMatches(g,category));
 $('project-detail').hidden=true;$('project-grid').hidden=false;activeProject=null;
 $('project-grid').replaceChildren(...groups.map(g=>{const b=document.createElement('button');b.className='project-card';b.type='button';const img=document.createElement('img');img.src=g.photos[0].src;img.alt='';img.loading='lazy';img.width=g.photos[0].width;img.height=g.photos[0].height;const text=document.createElement('span');const title=document.createElement('strong');title.textContent=g.title;const sub=document.createElement('span');sub.textContent=`${g.category} · ${g.photos.length} photographs ↗`;text.append(title,sub);b.append(img,text);b.addEventListener('click',()=>openProject(g));return b;}));
 $('collection-status').textContent=`${groups.length} collections · ${groups.reduce((n,g)=>n+g.photos.length,0)} photographs`;
 for(const b of $('filters').children)b.setAttribute('aria-pressed',String(b.textContent===category));
}
function openProject(g){activeProject=g;shown=0;$('project-grid').hidden=true;$('project-detail').hidden=false;$('project-category').textContent=g.category;$('project-title').textContent=g.title;$('collection-grid').replaceChildren();morePhotos();history.replaceState(null,'',`#collection=${g.id}`);$('project-detail').scrollIntoView({block:'start'});$('project-detail').focus({preventScroll:true});}
function morePhotos(){if(!activeProject)return;const photos=activeProject.photos;const batch=photos.slice(shown,shown+24);$('collection-grid').append(...batch.map(imageCard));shown+=batch.length;$('project-status').textContent=`Showing ${shown} of ${photos.length} photographs`;$('load-more').hidden=shown>=photos.length;}
$('load-more').addEventListener('click',morePhotos);
$('back-projects').addEventListener('click',()=>{const id=activeProject?.id;const category=[...$('filters').children].find(b=>b.getAttribute('aria-pressed')==='true')?.textContent||'All work';filter(category);history.replaceState(null,'','#collections');$('collections').scrollIntoView();const index=collections.filter(g=>categoryMatches(g,category)).findIndex(g=>g.id===id);$('project-grid').children[index]?.focus({preventScroll:true});});
function moment(step=0){const fs=catalog.filter(p=>p.feature==='moment');momentIndex=(momentIndex+step+fs.length)%fs.length;render('moment-image',[fs[momentIndex]]);$('moment-label').textContent=fs[momentIndex].label;$('moment-count').textContent=`${String(momentIndex+1).padStart(2,'0')} / ${String(fs.length).padStart(2,'0')}`;}
$('moment-prev')?.addEventListener('click',()=>moment(-1));$('moment-next')?.addEventListener('click',()=>moment(1));
async function init(){try{const r=await fetch(new URL('selection.json',portfolioRoot));if(!r.ok)throw new Error('Selection unavailable');catalog=(await r.json()).map(p=>({...p,src:new URL(p.src,portfolioRoot).href}));if($('people-grid')){if($('opening'))render('opening',catalog.filter(p=>p.opening).sort((a,b)=>a.opening-b.opening));for(const img of ($('opening')?.querySelectorAll('img')||[])){img.loading='eager';img.fetchPriority='high';}render('people-grid',catalog.filter(p=>p.feature==='people'));render('organization-grid',catalog.filter(p=>p.feature==='organization'));moment();render('moment-pair',catalog.filter(p=>p.feature==='moment-pair'));render('celebration-grid',[...catalog.filter(p=>p.category==='Weddings & connection').slice(0,2),...catalog.filter(p=>p.category==='Creative portraits').slice(0,2)]);}const cr=await fetch(new URL('collections.json',portfolioRoot));if(!cr.ok)throw new Error('Collections unavailable');collections=(await cr.json()).filter(g=>g.photos.length).map(g=>({...g,photos:g.photos.map(p=>({...p,src:new URL(p.src,portfolioRoot).href}))}));for(const name of ['All work',...(categoryGroups[document.body.dataset.category]?[document.body.dataset.category]:[]),...new Set(collections.map(p=>p.category))]){const b=document.createElement('button');b.type='button';b.textContent=name;b.addEventListener('click',()=>filter(name));$('filters').append(b);}const requested=document.body.dataset.category||new URLSearchParams(location.search).get('category');filter(collections.some(g=>categoryMatches(g,requested))?requested:'All work');const deep=collections.find(g=>location.hash===`#collection=${g.id}`);if(deep)openProject(deep);if(!matchMedia('(prefers-reduced-motion: reduce)').matches){const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){e.target.classList.add('revealed');observer.unobserve(e.target);}},{threshold:.05});document.querySelectorAll('.chapter-heading').forEach(e=>observer.observe(e));}}catch{($('opening')||$('collection-status')).textContent='The photographs could not load. Please refresh the page or contact ZAH Media.';}}
init();
